<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); $g=$data['group']; ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($g['name']) ?> – Gruppenchat</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:900px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.msg{border-top:1px solid #e5e9ee;padding:12px 0}.muted{color:#66758a}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}textarea{width:100%;box-sizing:border-box;min-height:100px;padding:10px;border:1px solid #bac5d1;border-radius:8px;font:inherit}button{padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;font-weight:700}</style></head><body><main><p><a href="/community/groups">← Gruppen</a></p><h1><?= $e($g['name']) ?> · Chat</h1><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?><section class="card"><form method="post" action="/community/groups/<?= rawurlencode($g['id']) ?>/chat"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><textarea name="body" maxlength="10000" placeholder="Nachricht an die Gruppe" required></textarea><button type="submit">Senden</button></form></section><section class="card"><h2>Nachrichten</h2><?php foreach($data['messages'] as $m):?><div class="msg"><strong><a href="/community/u/<?= rawurlencode($m['username']) ?>">@<?= $e($m['username']) ?></a></strong><p><?= nl2br($e($m['body'])) ?></p><small class="muted"><?= $e($m['created_at']) ?></small></div><?php endforeach;?><?php if(!$data['messages']):?><p class="muted">Noch keine Gruppennachrichten.</p><?php endif;?></section></main></body></html>